// Velure — plan which dates to check. Works for both triggers:
// the chat tool (date_from, days) and the public webhook (?date=YYYY-MM-DD).
const MAX_TOOL_DAYS = 5;    // open days per tool call (keeps one Notion page <= 100 rows)
const MAX_DAYS_AHEAD = 60;

// Phoenix is UTC-7 all year (no DST)
const PHX_OFFSET_MS = 7 * 3600 * 1000;
const ymd = (d) => d.toISOString().slice(0, 10);
const addDays = (key, n) => {
  const [y, m, d] = key.split('-').map(Number);
  return ymd(new Date(Date.UTC(y, m - 1, d + n)));
};
const isSunday = (key) => new Date(key + 'T12:00:00Z').getUTCDay() === 0;
const isDateKey = (v) => /^\d{4}-\d{2}-\d{2}$/.test(v) && !isNaN(Date.parse(v + 'T12:00:00Z'));

const today = ymd(new Date(Date.now() - PHX_OFFSET_MS));
const min = addDays(today, 1);
const max = addDays(today, MAX_DAYS_AHEAD);

const j = $input.first().json;
const fromWebhook = !!(j.headers && (j.query || j.body));
const src = fromWebhook ? { ...(j.body || {}), ...(j.query || {}) } : j;
const notes = [];
const dates = [];

if (fromWebhook) {
  // The booking form asks for exactly one date.
  const date = String(src.date ?? '').trim();
  if (isDateKey(date) && date >= min && date <= max && !isSunday(date)) dates.push(date);
} else {
  let start = String(src.date_from ?? '').trim();
  let days = Math.round(Number(src.days));
  if (!Number.isFinite(days) || days < 1) days = 1;
  if (days > MAX_TOOL_DAYS) {
    notes.push(`days is limited to ${MAX_TOOL_DAYS}; call again with a later date_from for more.`);
    days = MAX_TOOL_DAYS;
  }
  if (!isDateKey(start)) {
    notes.push(`date_from was missing or invalid, so the search starts tomorrow (${min}).`);
    start = min;
  } else if (start < min) {
    notes.push(`Online booking starts tomorrow (${min}); earlier dates cannot be booked online.`);
    start = min;
  }
  if (start > max) {
    notes.push(`Online booking is open up to ${max} only.`);
  }
  for (let d = start; d <= max && dates.length < days; d = addDays(d, 1)) {
    if (isSunday(d)) {
      if (d === start) notes.push(`${d} is a Sunday; Velure is closed on Sundays.`);
      continue;
    }
    dates.push(d);
  }
}

// Notion filter: confirmed bookings whose Slot key starts with one of the dates.
// With no dates, a never-matching key keeps the query valid and returns nothing.
const keys = dates.length ? dates : ['0000-00-00'];
const filter = {
  and: [
    { property: 'Status', select: { equals: 'Confirmed' } },
    { or: keys.map((d) => ({ property: 'Slot key', rich_text: { starts_with: d } })) },
  ],
};

return [{ json: { fromWebhook, today, min, max, dates, notes, filter } }];

// Velure — turn confirmed bookings into free times per date.
const SLOTS = ['09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30','13:00','13:30',
  '14:00','14:30','15:00','15:30','16:00','16:30','17:00','17:30','18:00'];

const plan = $('Plan Range').first().json;
const res = $input.first().json || {};
const ok = Array.isArray(res.results);

const taken = {};
if (ok) {
  for (const page of res.results) {
    const rt = (page.properties && page.properties['Slot key'] && page.properties['Slot key'].rich_text) || [];
    const key = rt.map((r) => r.plain_text || (r.text && r.text.content) || '').join('').trim();
    const [d, t] = key.split('T');
    if (d && t) (taken[d] = taken[d] || new Set()).add(t);
  }
}

if (plan.fromWebhook) {
  const date = plan.dates[0] || null;
  const body = ok
    ? { ok: true, date, bookable: !!date, taken: date ? [...(taken[date] || [])].sort() : [] }
    : { ok: false, error: 'unavailable' };
  return [{ json: { fromWebhook: true, status: ok ? 200 : 502, body } }];
}

if (!ok) {
  return [{ json: { fromWebhook: false, result: {
    ok: false,
    error: 'Availability could not be checked right now. The booking panel on the website shows live times.',
  } } }];
}

const label = (key) => new Date(key + 'T12:00:00Z').toLocaleDateString('en-US', {
  weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC',
});

const days = plan.dates.map((d) => {
  const t = taken[d] || new Set();
  const free = SLOTS.filter((s) => !t.has(s));
  return { date: d, label: label(d), free };
});

const lines = days.map((d) =>
  `${d.label} (${d.date}): ${d.free.length ? d.free.join(', ') : 'fully booked'}`);

return [{ json: { fromWebhook: false, result: {
  ok: true,
  today_in_scottsdale: plan.today,
  bookable_range: `${plan.min} to ${plan.max}, Monday to Saturday`,
  times_format: '24-hour HH:mm, Arizona time. Show them to the visitor as 10:30 AM.',
  free_times: lines.length ? lines.join('\n') : 'No bookable dates in the requested range.',
  notes: plan.notes.join(' '),
} } }];
